syntax:
template<typename T>
void forwardFunction(T&& arg) {
    // Implementation note: Use std::forward to preserve the value category
    // std::forward<T>(arg) reintroduces the original rvalueness if it was an rvalue
    someOtherFunction(std::forward<T>(arg));
}
// Notes: T&& is a forwarding reference, not a traditional rvalue reference. The compiler performs type deduction during overload resolution, collapsing references as per C++ rules (e.g., lvalue& && becomes lvalue&). This ensures efficient forwarding without losing const or volatile qualifiers.

code_example:
#include <iostream>
#include <utility>  // For std::forward
#include <string>
template<typename T>
void printWrapper(T&& value) {
    std::cout << "Forwarded value: " << std::forward<T>(value) << std::endl;
}
int main() {
    std::string str = "Hello";
    printWrapper(str);  // Forwards as lvalue
    printWrapper(std::string("World"));  // Forwards as rvalue
    return 0;
}
